let particles;

// let field
let NUM_STARS = 200;
let starX, starY, starBrightness;

function setup() {
  createCanvas(768, 768);
  colorMode(RGB, 255);
  background(0, 0, 12);

  fluidSolver = new NavierStokesFluidSolver();
  numberOfParticles = int(pow)(2, 15);
  particles = new Array(numberOfParticles);
  fluidViscosity = 0.00025;
  fluidDiffusion = 0.03;
  velocityScaleFactor = 10;
  maxMouseVelocity = 10;

  initializeParticles();
  initializeStars();
}

function initializeStars() {
  starX = new Array(NUM_STARS);
  starY = new Array(NUM_STARS);
  starBrightness = new Array(NUM_STARS);
  for (i = 0; i < NUM_STARS; i++) {
    starX[i] = random(width);
    starY[i] = random(height);
    starBrightness[i] = random(40, 160);
  }
}

function initializeParticles() {
  for (i = 0; i < numberOfParticles - 1; i++) {
    particles[i] = new Particle();
    particles[i].x = random(width);
    particles[i].y = random(height);
    particles[i].size = random(1, 3.5);
    particles[i].alpha = random(140, 255);
  }
}

function draw() {
  updateMouseInteraction();
  clearCanvas();
  drawStars();
  let timeStep = 1.0 / frameRate;
  fluidSolver.updateSimulation(timeStep, fluidViscosity, fluidDiffusion);
  particleVelocityScale = velocityScaleFactor * 60.0 / frameRate;
  renderParticles();
}

function clearCanvas() {
  // let space fade — very slow trail decay
  noStroke();
  fill(0, 0, 12, 25);
  rect(0, 0, width, height);

  // let vignette — darkens edges, brightens center slightly
  for (r = width; r > 0; r -= 20) {
    let alpha = map(r, 0, width, 0, 18);
    fill(0, 0, 8, alpha);
    ellipse(width / 2, height / 2, r, r);
  }
}

function drawStars() {
  noStroke();
  for (i = 0; i < NUM_STARS; i++) {
    // let twinkle
    let twinkle = starBrightness[i] + random(-12, 12);
    twinkle = constrain(twinkle, 20, 180);
    fill(200, 210, 255, twinkle);
    let sz = random(1) > 0.97 ? 2.0 : 1.0; // occasional slightly larger star
    ellipse(starX[i], starY[i], sz, sz);
  }
}

function renderParticles() {
  let gridSize = NavierStokesFluidSolver.GRID_SIZE;
  let cellHeight = height / gridSize;
  let cellWidth = width / gridSize;

  for (let particle of particles) {
    if (particle != null) {
      let cellX = floor(particle.x / cellWidth);
      let cellY = floor(particle.y / cellHeight);

      let velocityX = float(fluidSolver.getVelocityX)(cellX, cellY);
      let velocityY = float(fluidSolver.getVelocityY)(cellX, cellY);

      let localX = particle.x - cellX * cellWidth - cellWidth / 2;
      let localY = particle.y - cellY * cellHeight - cellHeight / 2;

      let neighborX, neighborY, xDirection, yDirection;
      if (localX > 0) { neighborX = Math.min(gridSize, cellX + 1); xDirection = 1; }
      else             { neighborX = Math.max(0, cellX - 1);        xDirection = -1; }
      if (localY > 0) { neighborY = Math.min(gridSize, cellY + 1); yDirection = 1; }
      else             { neighborY = Math.max(0, cellY - 1);        yDirection = -1; }

      let vxNX  = float(fluidSolver.getVelocityX)(neighborX, cellY);
      let vxNY  = float(fluidSolver.getVelocityX)(cellX, neighborY);
      let vxNXY = float(fluidSolver.getVelocityX)(neighborX, neighborY);
      let vyNX  = float(fluidSolver.getVelocityY)(neighborX, cellY);
      let vyNY  = float(fluidSolver.getVelocityY)(cellX, neighborY);
      let vyNXY = float(fluidSolver.getVelocityY)(neighborX, neighborY);

      velocityX = lerp(
        lerp(velocityX, vxNX, xDirection * localX / cellWidth),
        lerp(vxNY, vxNXY, xDirection * localX / cellWidth),
        yDirection * localY / cellHeight
      );
      velocityY = lerp(
        lerp(velocityY, vyNX, xDirection * localX / cellWidth),
        lerp(vyNY, vyNXY, xDirection * localX / cellWidth),
        yDirection * localY / cellHeight
      );

      particle.x += velocityX * particleVelocityScale;
      particle.y += velocityY * particleVelocityScale;

      if (particle.x < 0 || particle.x >= width)  particle.x = random(width);
      if (particle.y < 0 || particle.y >= height) particle.y = random(height);

      let speed = sqrt(velocityX * velocityX + velocityY * velocityY);
      let brightness = constrain(speed * 90, 20, particle.alpha);

      // let shifts cyan → blue-white → pale violet with speed
      let t = constrain(speed * 4, 0, 1);
      let r = lerp(30,  200, t);
      let g = lerp(200, 220, t);
      let b = lerp(255, 255, t);

      noStroke();
      fill(r, g, b, brightness);
      ellipse(particle.x, particle.y, particle.size, particle.size);
    }
  }
}

